using HomeLibrary;
using Microsoft.AspNetCore.DataProtection;
using System.Text.Json;
public static class BatchRenewalTests {
 static void Check(bool value,string label){if(!value)throw new Exception(label);Console.WriteLine("PASS "+label);}
 static void Reject(Action action,string label){try{action();throw new Exception("Not rejected: "+label);}catch(LibraryError){Console.WriteLine("PASS "+label);}}
 static JsonElement Input(object value)=>JsonSerializer.SerializeToElement(value,Library.Json);
 static CatalogBatchRow Row(string isbn,string title,bool duplicate=false)=>new(JsonSerializer.Deserialize<Dictionary<string,JsonElement>>(Input(new{isbn,title,author="Author",collectionId="general",importNotes="Private migration note"}),Library.Json)!,duplicate);
 public static async Task Run(string directory,IDataProtectionProvider protection){
  Directory.CreateDirectory(directory);using var store=new Store(directory,protection);
  object Apply(string action,object input)=>store.Apply(new(action,Input(input),store.Read().Revision));
  Check(store.Read().State.Version==7,"format-7 startup and pre-migration backup");
  var rows=new List<CatalogBatchRow>{Row("9780140328721","Matilda"),Row("","Unnumbered family book")};var preview=CatalogBatch.Preview(store.Read().State,rows);Check(preview.All(r=>r.Valid)&&store.Read().State.Books.Count==0,"batch dry run assigns copies without writes and permits no ISBN");
  var request=new ActionRequest("addBooksBatch",Input(new{rows,revision=store.Read().Revision}),store.Read().Revision,Guid.NewGuid().ToString());store.Apply(request);store.Apply(request);Check(store.Read().State.Books.Count==2&&store.Read().State.Books[1].ImportNotes=="Private migration note","batch save is atomic, idempotent and preserves private source notes");
  var before=store.Read().Revision;Reject(()=>Apply("addBooksBatch",new{rows=new[]{Row("9780141439518","Valid first"),Row("bad","Invalid second")}}),"invalid batch rejects all rows");Check(store.Read().Revision==before&&store.Read().State.Books.Count==2,"failed batch leaves catalog and revision unchanged");
  var duplicate=CatalogBatch.Preview(store.Read().State,[Row("9780140328721","Matilda")]);Check(!duplicate[0].Valid,"duplicates require deliberate additional-copy confirmation");Apply("addBooksBatch",new{rows=new[]{Row("9780140328721","Matilda",true)}});Check(store.Read().State.Books.Count==3,"explicit repeated ISBN adds another physical copy");
  var many=CatalogBatch.Preview(store.Read().State,[Row("bad","Bad"),Row("9780141439518","Next")]);Check(!many[0].Valid&&many[1].Valid&&many[1].Book!.Id=="BK-0004","invalid preview rows do not pollute subsequent rows or allocation");
  var parsed=JsonSerializer.SerializeToElement(CatalogCsv.Parse("\uFEFFTitle,Author,Notes\r\n\"A, book\",Writer,\"First line\nSecond \"\"quote\"\"\"\r\n"),Library.Json);Check(parsed.GetProperty("records")[0][0].GetString()=="A, book"&&parsed.GetProperty("records")[0][2].GetString()!.Contains("Second \"quote\""),"CSV BOM, CRLF, quoted commas/newlines/escaped quotes");Reject(()=>CatalogCsv.Parse("Title,Title\nA,B"),"CSV duplicate headers rejected");Reject(()=>CatalogCsv.Parse("Title,Author\n\"Unclosed,X"),"malformed CSV rejected");Reject(()=>CatalogCsv.Parse("Title,Author\nA,B,C"),"mismatched CSV columns rejected");
  Apply("addBorrower",new{name="Borrower",contact="borrower@example.test"});Apply("addBorrower",new{name="Other borrower",contact=""});Apply("checkout",new{copyId="BK-0001",borrowerId="BR-0001",checkoutDate=Library.Today,dueDate=Library.Today});
  using var accounts=new BorrowerAccounts(directory);var account=accounts.Register(new("renew.reader","Borrower recovery test passphrase","Borrower","borrower@example.test",""));account=accounts.Approve(new(account.Id,BorrowerId:"BR-0001"),store);var other=accounts.Register(new("other.reader","Other recovery test passphrase","Other borrower","",""));other=accounts.Approve(new(other.Id,BorrowerId:"BR-0002"),store);var loan=store.Read().State.Loans.Single();
  Reject(()=>store.AccountAction(other,new("requestRenewal",Input(new{loanId=loan.Id}),store.Read().Revision)),"borrowers cannot renew another person's loan");Reject(()=>store.PersonalAction(account.ReaderId,new("requestRenewal",Input(new{loanId=loan.Id}),store.Read().Revision)),"personal reading links cannot renew operational loans");
  store.AccountAction(account,new("requestRenewal",Input(new{loanId=loan.Id}),store.Read().Revision));loan=store.Read().State.Loans.Single();Check(loan.DueDate==Library.Today&&loan.Renewals.Single().Status=="pending","default renewal requests await approval without changing due date");Reject(()=>store.AccountAction(account,new("requestRenewal",Input(new{loanId=loan.Id}),store.Read().Revision)),"duplicate pending renewal rejected");
  Apply("approveRenewal",new{loanId=loan.Id,renewalId=loan.Renewals.Single().Id});loan=store.Read().State.Loans.Single();Check(loan.DueDate==DateOnly.Parse(Library.Today).AddDays(14).ToString("yyyy-MM-dd")&&loan.Renewals.Single().Status=="approved","approval extends due date and records history");Reject(()=>Apply("approveRenewal",new{loanId=loan.Id,renewalId=loan.Renewals.Single().Id}),"renewal replay rejected");
  Apply("setRenewalPolicy",new{enabled=true,automatic=true,days=7,maximum=2});store.AccountAction(account,new("requestRenewal",Input(new{loanId=loan.Id}),store.Read().Revision));loan=store.Read().State.Loans.Single();Check(loan.Renewals.Count(r=>r.Status=="approved")==2,"configured automatic renewal applies once");Reject(()=>store.AccountAction(account,new("requestRenewal",Input(new{loanId=loan.Id}),store.Read().Revision)),"per-loan renewal limit enforced");
  var conflict=store.Read().State;conflict.RenewalPolicy.Maximum=3;conflict.Requests.Add(new(){Id="conflict",CopyId=loan.CopyId,Status="pending"});Check(Renewals.Ineligible(conflict,conflict.Loans.Single())!.Contains("request"),"open requests prevent renewal");
  Apply("setRenewalPolicy",new{enabled=true,automatic=false,days=7,maximum=3});store.AccountAction(account,new("requestRenewal",Input(new{loanId=loan.Id}),store.Read().Revision));Apply("returnBook",new{copyId=loan.CopyId});Check(store.Read().State.Loans.Single().Renewals.Last().Status=="cancelled","return cancels a pending renewal");
  var session=accounts.Login(new(account.Username,"Borrower recovery test passphrase"));Check(accounts.PrepareEmailReset("unknown","https://library.example.test",store)==null&&accounts.PrepareEmailReset(other.Username,"https://library.example.test",store)==null,"unknown and non-email accounts cannot generate emailed reset links");var reset=accounts.PrepareEmailReset(account.Username,"https://library.example.test",store);Check(reset!=null&&accounts.PrepareEmailReset(account.Username,"https://library.example.test",store)==null,"email recovery uses saved contact with per-account cooldown");var token=reset!.Value.Link.Split("#reset=")[1];accounts.Reset(new(token,"Replacement recovery passphrase"));Reject(()=>accounts.Reset(new(token,"Another replacement passphrase")),"emailed reset token is single use");Check(accounts.Resolve(session)==null,"password reset revokes existing sign-in sessions");
  var sender=new FakeSender();using var reminders=new Reminders(directory,protection,store,sender);reminders.Save(new(){EmailPasswordRecovery=true,Host="smtp.example.test",Username="mail",Password="fake-test-secret",FromEmail="library@example.test"});await reminders.SendRecovery(reset.Value.Email,reset.Value.Link,CancellationToken.None);Check(sender.Mail?.Recipient==account.Contact&&sender.Mail.Body.Contains("#reset=")&&sender.Mail.Body.Contains("encrypted personal"),"transactional recovery mail uses configured sender and distinguishes private-list recovery");
  Check(Directory.GetFiles(Path.Combine(directory,"backups"),"before-batch-*.hlbackup").Length>0,"private pre-import recovery backup saved");
 }
 sealed class FakeSender:IReminderSender {public ReminderMail? Mail;public Task Send(ReminderConfiguration settings,ReminderMail mail,CancellationToken stop){Mail=mail;return Task.CompletedTask;}}
}
